/*! Car tire squeal / skid loop. Original recording: audible-edge (Tom Haigh).
 * Loop edit: qubodup. CC BY 3.0 https://creativecommons.org/licenses/by/3.0/
 * Source: https://opengameart.org/content/car-tire-squeal-skid-loop
 * SIDEWAYS adaptation: resampled to 48 kHz PCM16, bandpass 280 Hz..10 kHz,
 * DC removal, normalized level and 30 ms loop crossfade. No endorsement implied.
 * Attribution also in audio/ATTRIBUTION.txt. */
function decodePCM(base64){const bytes=atob(base64),out=new Float32Array(bytes.length/2);for(let i=0;i<out.length;i++){let n=bytes.charCodeAt(i*2)|(bytes.charCodeAt(i*2+1)<<8);if(n>32767)n-=65536;out[i]=n/32768;}return out;}
export const TYRE_SAMPLE_RATE=48000;
export const TYRE_SAMPLE=decodePCM("");

// Offline-rendered MotorLab 1.5 I4 at approximately 1800 RPM, for distant NPCs only.
export const TRAFFIC_SAMPLE_RATE=24000;
export const TRAFFIC_SAMPLE=decodePCM("");
